"""integer kth root of n"""
def integer_root(n: Any, k: Any) -> object {
    (u, s) = (n, (n + 1));
    while (u < s) {
        s = u;
        t = ((k - 1) * s) + (n // pow(s, (k - 1)));
        u = t // k;
    }
    return s;
}

"""
    Auto parses the help dialogs provided by developers in the doc strings.
    This is denoted by helpme - text and then a blank line.

    e.g.

    Function doc string
    helpme - more end user friendly message about what this will do

    my arguments...

    """
def parse_help(help_str: Any) -> object {
    result = None;
    if (help_str is not None) {
        if ('helpme' in help_str) {
            z = help_str.split('helpme');
            result = z[-1].split('-')[-1].strip();
        }
    }
    return result;
}

"""Check if an edge `e` is in a face `f`.

       Example:
       >>> e = (0, 1)
       >>> f = (1, 2, 3, 0)
       >>> has_edge(e, f)
       >>> True  # because 0, 1 are adjacent in f (first and last)
    """
def has_edge(e: Any, f: Any) -> object {
    for pair in zip(f, (f[1:] + (f[0], ))) {
        if ((e == pair) or (e == pair[::-1])) {
            return True;
        }
    }
    return False;
}

"""Returns a list of tuples that contains element pairs from `l` in all possible combinations
    without repeats irrespective of order.

    :param list l: list to parse into pairs
    :return: element_pairs, list of tuples for each pair
    :rtype: list
    """
def all_list_element_combinations_as_pairs(l: Any) -> object {
    element_pairs = [];
    for i in range(len(l)) {
        element_pairs += [(l[i], l[j]) for j in range(i, len(l))];
    }
    return element_pairs;
}

